  "advice.overspend.title": "You spend more than you earn",
  "advice.overspend.msg": "Your expenses exceed your monthly net. Cut non-essential subscriptions first, then renegotiate utility, insurance and bank fees before debt builds up.",
  "advice.debt35.title": "Debt above 35%",
  "advice.debt35.msg": "Your loan payments represent {pct}% of your net income. The common safety threshold is 35% — beyond it, be cautious and consider refinancing.",
  "advice.debt25.title": "Debt to watch",
  "advice.debt25.msg": "Your loan payments are at {pct}%. You're getting close to the risky zone (35%). Avoid taking on new credit until you have a solid positive balance.",
  "advice.rentHigh.title": "Rent is high",
  "advice.rentHigh.msg": "Your rent weighs {pct}% of your net income. The classic 1/3 rule recommends staying below 33%. Consider flat-sharing, moving or negotiating the annual increase.",
  "advice.rentOk.title": "Rent under control",
  "advice.rentOk.msg": "Your rent only represents {pct}% of your net — excellent margin to save or invest.",
  "advice.needsCrit.title": "Critical needs level",
  "advice.needsCrit.msg": "Your fixed needs (rent + loans + mandatory expenses) reach {pct}% of your net. Above 60%, your flexibility disappears. Start by renegotiating recurring contracts (insurance, energy, telecoms).",
  "advice.needsHigh.title": "Needs above 50%",
  "advice.needsHigh.msg": "Your needs represent {pct}% of your net. The 50/30/20 rule targets 50%. Cutting {gap}% directly frees savings.",
  "advice.needsOk.title": "Needs under control",
  "advice.needsOk.msg": "Your needs are at {pct}% — below the 50% threshold of the 50/30/20 rule. A solid base to save.",
  "advice.wantsHigh.title": "Wants are very high",
  "advice.wantsHigh.msg": "You put {pct}% into wants (vs the recommended 30%). A few fewer outings can free hundreds to save or invest.",
  "advice.wantsBitHigh.title": "Wants a bit high",
  "advice.wantsBitHigh.msg": "You're at {pct}% on wants. Slightly above the 30% threshold — nothing alarming as long as savings keep up.",
  "advice.noWants.title": "No leisure declared",
  "advice.noWants.msg": "No leisure budget? Allow yourself an enjoyment envelope — a balanced budget lasts because it's livable.",
  "advice.noSavings.title": "No savings",
  "advice.noSavings.msg": "You barely save anything. Set up an automatic transfer this month to a savings account — even 50 / month, the goal is the habit.",
  "advice.lowSavings.title": "Low savings",
  "advice.lowSavings.msg": "You save {pct}% of your net. The 50/30/20 goal is 20%. Step 1: build an emergency fund of 3 to 6 months of expenses.",
  "advice.savingsBuilding.title": "Savings building up",
  "advice.savingsBuilding.msg": "You save {pct}%. To reach 20%, automate a transfer at the start of the month — what you don't see, you don't spend.",
  "advice.goodSavings.title": "Excellent savings",
  "advice.goodSavings.msg": "You save {pct}% — above the 20% threshold. Diversify: savings account for safety, stock plan / brokerage for long-term growth.",
  "advice.maxSavings.title": "Maximum savings",
  "advice.maxSavings.msg": "You save {pct}% of your net — that's rare. Think long-term: pension plan, life insurance, rental real estate.",
  "advice.captureMargin.title": "You have a margin — capture it",
  "advice.captureMargin.msg": "You have {pct}% left at the end of the month but no savings declared. Without automation, money disappears into non-essential spending. Schedule a transfer.",
  "advice.fixedExpenses.title": "Fixed expenses outside housing",
  "advice.fixedExpenses.msg": "Your needs spending excluding rent/loans represents {pct}% of your net. Reviewing contracts (energy, telecom, insurance) once a year easily recovers 30 to 80 / month.",
  "advice.rentLoan.title": "You combine rent and loan",
  "advice.rentLoan.msg": "Having rent + loan in parallel is heavy. If the loan is for a property you don't occupy, make sure the rent received covers at least the monthly payment.",
  "advice.lowExpenses.title": "Think about forgotten expenses",
  "advice.lowExpenses.msg": "Your expenses look very low compared to your income. Make sure you've entered subscriptions, groceries, energy — an underestimated budget gives misleading advice.",
  "advice.investProfile.title": "Investment-friendly profile",
  "advice.investProfile.msg": "With your surplus and contained housing cost, you can move to the next step: monthly DCA into a World ETF, or a rental investment simulation.",
  "advice.emergency.title": "Build an emergency fund",
  "advice.emergency.msg": "Aim for 3 to 6 months of fixed expenses in liquid savings accounts before investing in the stock market. It's your financial airbag.",
  "advice.perfect.title": "Exemplary budget",
  "advice.perfect.msg": "You tick all 3 boxes of 50/30/20 and you're not overspending. Keep going and put your savings to work (stock plan, life insurance, real estate).",
  "advice.notEnoughData.title": "Not enough data yet",
  "advice.notEnoughData.msg": "Add more categories to get targeted advice.",

